#!/usr/bin/env node
// bmad-generated:378f7f85
// BMAD Swarm - PreToolUse gate: the NIGHT FLOOR — the constitutional
// destructive-action denylist of /sleep mode (diverge-overnight §3.1, D-034,
// phase5-decomposition §3.1). Generated by bmad-swarm - do not edit manually.
//
// SECURITY-CRITICAL, ENFORCEMENT (D-039): this is the one mechanical wall of the
// overnight beast. The safety story of /sleep — "worst case is deleting a branch"
// — is only TRUE if the irreversible, world-facing action set cannot be reached
// while the human sleeps. This hook is that wall.
//
// CHARTER-ACTIVATED. Dormant unless a night charter is open (the pointer
// artifacts/delivery/.night-charter-current names an active charter). While a
// night is armed it DENIES the destructive/irreversible set for EVERY agent
// (orchestrator and teammates alike):
//   - git push / merge / rebase / reset --hard / branch -D / tag (never-merge is
//     a floor; branch-delete of unmerged night work is loss)
//   - npm|yarn|pnpm publish, npm version, package-registry writes
//   - deploy CLIs (terraform/kubectl apply, ansible-playbook, vercel/netlify/
//     serverless/fly/heroku/wrangler/firebase/gcloud/aws deploy)
//   - real-data migrations + destructive SQL (DROP/TRUNCATE, prisma migrate
//     deploy, flyway/alembic/knex/rails migrate)
//   - destructive/spending external calls (curl/wget POST|PUT|DELETE|PATCH|--data)
//   - rm/mv outside the worktree tree; writes to absolute paths outside the tree
//   - self-legislation: writes/redirects to .claude/**, any hook, the charter, the
//     pointer, or the human-wake marker (the swarm cannot re-legislate its floor)
//   - THE SECURITY RESIDUAL (§2.1): interpreter-escape patterns for night
//     teammates — node -e/--eval/-p, npx, python -c, perl/ruby -e, php -r, and
//     sh/bash -c wrappers (incl. env-prefix / timeout / xargs wrappers, caught by
//     scanning the whole command string). Fork A narrowed the orchestrator; this
//     closes the teammate half so "worst case = branch deletion" holds for every
//     agent at 3am. (Residual honestly noted: `node <written-file>.js` is not an
//     inline-eval and is not denied here — full closure needs the Fork A shell
//     allowlist; this hook is defense-in-depth on top of it, not a substitute.)
//   - anything in the charter's extra_deny[] (charters may only NARROW — there is
//     no allow direction in the schema, D-034 §3.5.2)
//
// FAIL-CLOSED. A pointer that names a missing or unparseable charter, or a
// charter with no numeric ends_epoch_ms, keeps the floor ARMED (kill-list #9,
// failure-mode #8/#10). The floor lifts only when the human-wake marker appears
// (human is driving) OR now > ends + grace (H5-2(d) default 2h) — whichever first.
//
// EVERY DENY IS LOGGED. Best-effort red-banner row to the task-ledger via the
// pinned record.cjs (task=night-floor event=denied) so a blocked 3am `git push`
// still shows up in the morning report (failure-mode #2).

'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const DEFAULT_GRACE_MS = 2 * 60 * 60 * 1000;

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (c) => { input += c; });
process.stdin.on('end', () => {
  let event;
  try { event = JSON.parse(input); } catch { process.exit(0); }

  const projectRoot = normalizeSlashes(process.env.CLAUDE_PROJECT_DIR || event.cwd || process.cwd());
  const toolCwd = normalizeSlashes(event.cwd || projectRoot);

  // Evaluate the floor. Any error while a night is open FAILS CLOSED (armed).
  let floor;
  try { floor = evaluateFloor(projectRoot); }
  catch { floor = { armed: true, extraDeny: [], reason: 'charter evaluation threw' }; }
  if (!floor.armed) { process.exit(0); }

  const toolInput = event.tool_input || {};

  // (A) Bash branch — keyed on payload shape, not tool_name.
  if (typeof toolInput.command === 'string') {
    const hit = bashViolation(toolInput.command, floor.extraDeny, projectRoot, toolCwd);
    if (hit) { denyWithLog(projectRoot, 'Bash', hit, toolInput.command); }
    process.exit(0);
  }

  // (B) File-writing tools all name a single target path.
  const filePath = toolInput.file_path || toolInput.notebook_path || toolInput.path || '';
  if (!filePath) { process.exit(0); }
  const fileHit = fileViolation(filePath, projectRoot, toolCwd);
  if (fileHit) { denyWithLog(projectRoot, 'Write', fileHit, filePath); }
  process.exit(0);
});

// --- floor evaluation ------------------------------------------------------

function evaluateFloor(projectRoot) {
  const pointer = projectRoot + '/artifacts/delivery/.night-charter-current';
  if (!fs.existsSync(pointer)) return { armed: false };            // no night → dormant
  let base;
  try { base = fs.readFileSync(pointer, 'utf8').trim(); } catch { return { armed: true, extraDeny: [], reason: 'pointer unreadable' }; }
  if (!base || base.includes('/') || base.includes('..')) return { armed: true, extraDeny: [], reason: 'pointer malformed' };
  const charterFile = projectRoot + '/artifacts/delivery/' + base;
  if (!fs.existsSync(charterFile)) return { armed: true, extraDeny: [], reason: 'charter missing (dangling pointer)' };
  let text;
  try { text = fs.readFileSync(charterFile, 'utf8'); } catch { return { armed: true, extraDeny: [], reason: 'charter unreadable' }; }

  const endsM = /ends_epoch_ms:\s*(\d+)/.exec(text);
  if (!endsM) return { armed: true, extraDeny: parseExtraDeny(text), reason: 'no ends_epoch_ms (corrupt clock)' };
  const endsEpoch = parseInt(endsM[1], 10);
  const graceM = /grace_ms:\s*(\d+)/.exec(text);
  const graceMs = graceM ? parseInt(graceM[1], 10) : DEFAULT_GRACE_MS;
  const extraDeny = parseExtraDeny(text);

  // Human-wake marker → the human is driving; the floor lifts (named residual).
  if (fs.existsSync(projectRoot + '/.claude/hooks/.human-wake')) return { armed: false };
  // Grace expired → floor lifts (H5-2(d)); before that, armed.
  if (Date.now() > endsEpoch + graceMs) return { armed: false };
  return { armed: true, extraDeny, reason: 'charter active' };
}

function parseExtraDeny(text) {
  const m = /extra_deny:\s*\[([^\]]*)\]/.exec(text);
  if (!m || !m[1].trim()) return [];
  return m[1].split(',').map((s) => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
}

// --- Bash deny set ---------------------------------------------------------

// Irreversible / world-facing / self-legislating command shapes. Each entry is a
// {re, label}. Over-denial is preferred to under-denial here (fail-closed stance):
// a night agent that cannot `git tag -l` loses nothing; a night agent that CAN
// `git push` breaks the whole safety story.
const BASH_DENY = [
  // git — never-merge + no history rewrite + no branch-delete of unmerged work
  { re: /\bgit\b[^\n]*\bpush\b/, label: 'git push (never push overnight — the floor)' },
  { re: /\bgit\b[^\n]*\bmerge\b/, label: 'git merge (never-merge is a constitutional floor at every trust level)' },
  { re: /\bgit\b[^\n]*\brebase\b/, label: 'git rebase (history rewrite)' },
  { re: /\bgit\b[^\n]*\breset\b[^\n]*--hard\b/, label: 'git reset --hard (irreversible working-tree loss)' },
  { re: /\bgit\s+branch\b[^\n]*(?:-D\b|--delete[^\n]*--force|--force[^\n]*--delete)/, label: 'git branch -D (deletes unmerged night work)' },
  { re: /\bgit\b[^\n]*\btag\b/, label: 'git tag (release tagging)' },
  { re: /\bgit\b[^\n]*\bclean\b[^\n]*-[a-z]*f/, label: 'git clean -f (irreversible untracked deletion)' },
  // publish / version / registry
  { re: /\b(npm|yarn|pnpm)\s+publish\b/, label: 'package publish' },
  { re: /\bnpm\s+version\b/, label: 'npm version (tags + version bump)' },
  { re: /\b(gem\s+push|cargo\s+publish|twine\s+upload|poetry\s+publish|dotnet\s+nuget\s+push)\b/, label: 'registry publish' },
  // deploy CLIs
  { re: /\bterraform\s+(apply|destroy)\b/, label: 'terraform apply/destroy' },
  { re: /\bkubectl\s+(apply|delete|replace|create|patch)\b/, label: 'kubectl mutation' },
  { re: /\bansible-playbook\b/, label: 'ansible-playbook' },
  { re: /\b(vercel|netlify|serverless|sls|flyctl|fly|heroku|wrangler|firebase|eb|gcloud|aws|az|render|railway|supabase)\b[^\n]*\bdeploy\b/, label: 'PaaS deploy' },
  { re: /\bwrangler\s+publish\b/, label: 'wrangler publish' },
  { re: /\bgcloud\b[^\n]*\b(run|app|functions)\b[^\n]*\bdeploy\b/, label: 'gcloud deploy' },
  // real-data migrations + destructive SQL
  { re: /\bDROP\s+(DATABASE|TABLE|SCHEMA|INDEX)\b/i, label: 'destructive SQL (DROP)' },
  { re: /\bTRUNCATE\s+(TABLE\s+)?\w/i, label: 'destructive SQL (TRUNCATE)' },
  { re: /\bprisma\s+(migrate\s+deploy|db\s+push)\b/, label: 'prisma production migration' },
  { re: /\b(flyway\s+migrate|alembic\s+upgrade|knex\s+migrate:latest|sequelize\s+db:migrate|rails\s+db:migrate|dbmate\s+up|goose\s+up)\b/, label: 'schema migration' },
  // destructive / spending external calls (GET reads pass)
  { re: /\b(curl|wget)\b[^\n]*(?:\s-X\s*(?:POST|PUT|DELETE|PATCH)|--request\s*(?:POST|PUT|DELETE|PATCH)|--method[=\s]*(?:POST|PUT|DELETE|PATCH)|\s--data\b|\s--data-\w+|\s--post-data\b|\s--post-file\b|\s--body-data\b|\s--body-file\b|\s-d\b|\s-F\b|\s--form\b|\s-T\b|\s--upload-file\b)/i, label: 'data-sending external call (curl/wget write method)' },
  // interpreter-escape patterns (the §2.1 teammate residual). Whole-string scan
  // means env-prefix / timeout / xargs wrappers are caught by the inner match.
  // Scan the WHOLE node command for an eval/print flag (not just the token right
  // after `node`), so a flag-separated escape (`node --require x -e "…"`) is
  // caught too. Legit night node usage (node --test, node <file>, node
  // .../record.cjs …) carries no ` -e/-p/--eval/--print`, so over-scan is safe.
  { re: /\b(node|nodejs)\b[^\n;|&]*\s-(?:-eval\b|-print\b|pe\b|e\b|p\b)/, label: 'node inline-eval (interpreter escape)' },
  { re: /\bnpx\b/, label: 'npx (arbitrary package execution)' },
  { re: /\b(python|python3|python2)\s+-c\b/, label: 'python -c (interpreter escape)' },
  { re: /\b(perl|ruby)\s+-e\b/, label: 'perl/ruby -e (interpreter escape)' },
  { re: /\bphp\s+-r\b/, label: 'php -r (interpreter escape)' },
  { re: /\b(sh|bash|zsh|dash|ksh)\s+-[a-zA-Z]*c\b/, label: 'shell -c wrapper (interpreter escape)' },
  { re: /(?:^|[\s;&|(])eval\s+\S/, label: 'shell eval builtin' },
];

// Path tokens whose write-shape is denied in a Bash command (self-legislation +
// charter/marker protection). Same technique as ledger-write-guard: the token
// must appear AS a write/redirect target, not merely be read.
function bashViolation(command, extraDeny, projectRoot, toolCwd) {
  const cmd = String(command);

  for (const d of BASH_DENY) {
    if (d.re.test(cmd)) return d.label;
  }
  // extra_deny substrings (charter narrowing)
  for (const sub of extraDeny) {
    if (sub && cmd.includes(sub)) return `charter extra_deny: ${JSON.stringify(sub)}`;
  }
  // self-legislation: write-shapes onto .claude/**, hooks, charter, pointer, marker
  if (bashWritesProtected(cmd)) return 'write/redirect to .claude/** / hook / charter / wake-marker (no self-legislation at night)';
  // rm/mv/cp with a target outside the worktree tree
  const outHit = bashOutOfTree(cmd, projectRoot, toolCwd);
  if (outHit) return outHit;
  return null;
}

// A redirect or write-binary aimed at a protected path token.
function bashWritesProtected(cmd) {
  // Protected path fragments (as they would appear in a command).
  const PROTECTED = [/\.claude\//, /night-charter[\w.-]*\.md/, /\.night-charter-current\b/, /\.human-wake\b/];
  const named = PROTECTED.some((re) => re.test(cmd));
  if (!named) return false;
  // Redirection onto any of them.
  if (/(?:>>?|&>|>\|)\s*(?:"[^"]*"|'[^']*'|[^\s|;&]*)(?:\.claude\/|night-charter[\w.-]*\.md|\.night-charter-current|\.human-wake)/.test(cmd)) return true;
  // Write/edit binaries anywhere (coarse backstop, consistent with ledger-guard).
  if (/\b(tee|dd|cp|mv|install|rsync|ln|truncate|patch|ed|ex|vim?|awk)\b/.test(cmd)) return true;
  if (/\bsed\b[^\n]*\s-i\b/.test(cmd)) return true;
  return false;
}

// rm / mv / cp whose target escapes the worktree tree (~, $HOME, absolute paths
// not under the project/worktree root, or ../ escapes). Deletion outside the
// sandbox is the class that falsifies "worst case = branch deletion".
function bashOutOfTree(cmd, projectRoot, toolCwd) {
  if (!/\b(rm|rmdir|mv|shred|unlink)\b/.test(cmd)) return null;
  // Tokenize crudely on whitespace; inspect path-like tokens.
  const tokens = cmd.split(/\s+/);
  for (const t of tokens) {
    if (!t || t.startsWith('-')) continue;
    if (/^~($|\/)/.test(t) || t.includes('$HOME')) return 'rm/mv targeting the home directory (outside the worktree)';
    if (path.posix.isAbsolute(normalizeSlashes(t))) {
      const abs = normalizeSlashes(path.posix.normalize(t));
      if (!underAnyRoot(abs, projectRoot, toolCwd)) return `rm/mv targeting ${t} (absolute path outside the worktree tree)`;
    } else if (normalizeSlashes(t).split('/').includes('..')) {
      const abs = normalizeSlashes(path.posix.normalize(toolCwd + '/' + t));
      if (!underAnyRoot(abs, projectRoot, toolCwd)) return `rm/mv targeting ${t} (escapes the worktree tree)`;
    }
  }
  return null;
}

// --- file-writing-tool deny set --------------------------------------------

function fileViolation(rawPath, projectRoot, toolCwd) {
  const abs = resolveAbs(rawPath, toolCwd);
  if (!abs) return null;
  // Out-of-tree write: escapes both the project root and the tool cwd (worktree).
  if (!underAnyRoot(abs, projectRoot, toolCwd)) return `write to ${rawPath} outside the worktree tree`;
  // Self-legislation: anything under .claude/, or the charter / pointer / marker.
  if (/\/\.claude(\/|$)/.test(abs) || abs.endsWith('/.human-wake')) return 'write to .claude/** or the wake marker (no self-legislation at night)';
  if (/\/artifacts\/delivery\/night-charter[\w.-]*\.md$/.test(abs) || abs.endsWith('/.night-charter-current')) return 'write to the night charter / pointer (only the pinned record.cjs may write it)';
  return null;
}

// --- shared path helpers ---------------------------------------------------

function normalizeSlashes(p) { return String(p == null ? '' : p).replace(/\\/g, '/'); }

function resolveAbs(rawPath, base) {
  const norm = normalizeSlashes(rawPath);
  if (!norm) return null;
  if (path.posix.isAbsolute(norm)) return path.posix.normalize(norm);
  return path.posix.normalize(normalizeSlashes(base) + '/' + norm);
}

function underRoot(abs, root) {
  const r = path.posix.normalize(normalizeSlashes(root));
  return abs === r || abs.startsWith(r.endsWith('/') ? r : r + '/');
}

function underAnyRoot(abs, projectRoot, toolCwd) {
  return underRoot(abs, projectRoot) || underRoot(abs, toolCwd);
}

// --- deny + red-banner log -------------------------------------------------

function denyWithLog(projectRoot, tool, reason, detail) {
  logRedBanner(projectRoot, tool, reason, detail);
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'deny',
      permissionDecisionReason:
        'NIGHT FLOOR: denied — ' + reason + '. A night charter is active; the '
        + 'destructive/irreversible set is off-limits until the human wakes (D-034). '
        + 'This attempt is logged to the task-ledger and will appear as a red banner '
        + 'in the morning report. Everything reversible runs free — work on a '
        + 'never-merged branch instead.',
    },
  }));
  process.exit(0);
}

// Best-effort: append a red-banner row via the pinned record.cjs (lock + atomic).
// Never blocks the deny — a logging failure must not fail-open.
function logRedBanner(projectRoot, tool, reason, detail) {
  try {
    const candidates = [
      projectRoot + '/.claude/bmad/bin/record.cjs',
      projectRoot + '/bin/record.cjs',
    ];
    const cli = candidates.find((p) => { try { return fs.existsSync(p); } catch { return false; } });
    if (!cli) return;
    const subject = (tool + ': ' + reason + ' — ' + String(detail || '').slice(0, 160)).slice(0, 240);
    spawnSync('node', [cli, 'task-event', '--task', 'night-floor', '--event', 'denied', '--detail', subject], {
      cwd: projectRoot,
      env: { ...process.env, CLAUDE_PROJECT_DIR: projectRoot },
      stdio: 'ignore',
      timeout: 5000,
    });
  } catch { /* logging is best-effort; the deny stands regardless */ }
}
